def solve(n):
    # Create a tessel Grid of size n x n
    grid = tessel.grid.Grid(n, n)

    # Fill the grid with 6 on the main diagonal
    for i in range(n):
        for j in range(n):
            if i == j:
                grid[i][j] = 6

    return grid
